define(['underscore','uiComponent','mage/translate','Magento_Checkout/js/model/payment/renderer-list','uiLayout','uiRegistry'],function(_,Component,$t,rendererList,layout,registry){'use strict';var vaultGroupName='vaultGroup';layout([{name:vaultGroupName,component:'Magento_Checkout/js/model/payment/method-group',alias:'vault',sortOrder:10,title:$t('Stored Cards')}]);registry.get(vaultGroupName,function(vaultGroup){_.each(window.checkoutConfig.payment.vault,function(config,index){rendererList.push({type:index,config:config.config,component:config.component,group:vaultGroup,typeComparatorCallback:function(typeA,typeB){return typeA.substring(0,typeA.lastIndexOf('_'))===typeB;}});});});return Component.extend({});});